/**
 * Trip Concierge client.
 *
 * - Edge mode: when VITE_SUPABASE_URL + VITE_SUPABASE_ANON_KEY are set, the
 *   itinerary is generated by the LLM-backed Supabase Edge Function
 *   (supabase/functions/trip-concierge).
 * - Local mode (default, and the fallback on ANY edge/network failure):
 *   a deterministic generator with curated data for popular Egypt driving
 *   routes plus a generic template for unknown routes. Fully bilingual.
 */

export type ConciergeLanguage = "en" | "ar";

export interface ItineraryStop {
  time: string;
  name: string;
  note: string;
}

export interface ItineraryDay {
  day: number;
  title: string;
  stops: ItineraryStop[];
}

export interface Itinerary {
  days: ItineraryDay[];
  tips: string[];
}

export interface TripPlanRequest {
  car: { name: string; type: string; seats: number };
  startDate: string;
  endDate: string;
  from: string;
  to: string;
  language: ConciergeLanguage;
}

export interface TripPlanResult {
  itinerary: Itinerary;
  /** "edge" = LLM via Supabase Edge Function, "local" = built-in generator. */
  source: "edge" | "local";
}

/* ------------------------------------------------------------------ */
/* Destinations offered in the picker                                  */
/* ------------------------------------------------------------------ */

interface Localized {
  en: string;
  ar: string;
}

export interface ConciergeDestination {
  id: string;
  name: Localized;
}

export const DESTINATIONS: ConciergeDestination[] = [
  { id: "north-coast", name: { en: "North Coast", ar: "الساحل الشمالي" } },
  { id: "alexandria", name: { en: "Alexandria", ar: "الإسكندرية" } },
  { id: "ain-sokhna", name: { en: "Ain Sokhna", ar: "العين السخنة" } },
  { id: "fayoum", name: { en: "Fayoum", ar: "الفيوم" } },
  { id: "hurghada", name: { en: "Hurghada", ar: "الغردقة" } },
  { id: "luxor", name: { en: "Luxor", ar: "الأقصر" } },
];

export function destinationLabel(id: string, language: ConciergeLanguage): string {
  const d = DESTINATIONS.find((x) => x.id === id);
  return d ? d.name[language] : id;
}

