/* ------------------------------------------------------------------ */
/* Local deterministic generator                                       */
/* ------------------------------------------------------------------ */

function normalizePlace(value: string): string {
  return value.trim().toLowerCase().replace(/\s+/g, "-");
}

function lookupRoute(from: string, to: string): RouteDef {
  const f = normalizePlace(from);
  const t = normalizePlace(to);
  // Giza departures share Cairo's highway network.
  const origins = f === "giza" ? [f, "cairo"] : f === "cairo" ? [f, "giza"] : [f];
  for (const origin of origins) {
    const route = ROUTES[`${origin}>${t}`];
    if (route) return route;
  }
  return genericRoute(from, to);
}

function tripDayCount(startDate: string, endDate: string): number {
  const start = new Date(`${startDate}T00:00:00`);
  const end = new Date(`${endDate}T00:00:00`);
  const diff = Math.round((end.getTime() - start.getTime()) / 86_400_000);
  return Math.min(7, Math.max(1, diff + 1));
}

function localizeStops(stops: StopDef[], language: ConciergeLanguage): ItineraryStop[] {
  return stops.map((s) => ({ time: s.time, name: s.name[language], note: s.note[language] }));
}

export function generateLocalItinerary(req: TripPlanRequest): Itinerary {
  const route = lookupRoute(req.from, req.to);
  const total = tripDayCount(req.startDate, req.endDate);
  const lang = req.language;

  const days: ItineraryDay[] = [
    { day: 1, title: route.outboundTitle[lang], stops: localizeStops(route.outbound, lang) },
  ];
  for (let d = 2; d < total; d++) {
    days.push({ day: d, title: route.exploreTitle[lang], stops: localizeStops(route.explore, lang) });
  }
  if (total >= 2) {
    days.push({ day: total, title: route.returnTitle[lang], stops: localizeStops(route.inbound, lang) });
  }

  return { days, tips: route.tips.map((tip) => tip[lang]) };
}

/* ------------------------------------------------------------------ */
/* Edge Function client with local fallback                            */
/* ------------------------------------------------------------------ */

function isItinerary(data: unknown): data is Itinerary {
  if (typeof data !== "object" || data === null) return false;
  const d = data as { days?: unknown; tips?: unknown };
  return (
    Array.isArray(d.days) &&
    d.days.length > 0 &&
    Array.isArray(d.tips) &&
    d.days.every(
      (day: unknown) =>
        typeof day === "object" &&
        day !== null &&
        typeof (day as ItineraryDay).title === "string" &&
        Array.isArray((day as ItineraryDay).stops),
    )
  );
}

async function fetchEdgeItinerary(
  req: TripPlanRequest,
  url: string,
  anonKey: string,
): Promise<Itinerary> {
  const res = await fetch(`${url.replace(/\/$/, "")}/functions/v1/trip-concierge`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${anonKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify(req),
  });
  if (!res.ok) throw new Error(`trip-concierge responded ${res.status}`);
  const data: unknown = await res.json();
  if (!isItinerary(data)) throw new Error("trip-concierge returned an invalid itinerary");
  return data;
}

/**
 * Generate an itinerary. Uses the Supabase Edge Function when configured,
 * and always falls back to the local generator on any failure so the
 * feature works offline and without a backend.
 */
export async function generateItinerary(req: TripPlanRequest): Promise<TripPlanResult> {
  const url = import.meta.env.VITE_SUPABASE_URL as string | undefined;
  const anonKey = import.meta.env.VITE_SUPABASE_ANON_KEY as string | undefined;

  if (url && anonKey) {
    try {
      const itinerary = await fetchEdgeItinerary(req, url, anonKey);
      return { itinerary, source: "edge" };
    } catch {
      // Network/config/model failure — degrade to the local generator.
    }
  }
  return { itinerary: generateLocalItinerary(req), source: "local" };
}
